    function OverrideDateValidation(newlanguage)
    {
        Globalize.culture(newlanguage);

        $.validator.methods.date = function (value, element) {
            var result = this.optional(element) ||
                ((Globalize.parseDate(value, "dd MMM yyyy")) != null);

            return result;
        }
    }


    function CheckCulture(newlanguage)
    {
        if (_CurrentCulture != newlanguage)
        {
            $.getScript("/Scripts/plugins/globalize/globalize.js",
                function ()
                {
                    $.getScript("/Scripts/plugins/globalize/cultures/" + "globalize.culture." + newlanguage + ".js",
                        function ()
                        {
                            _CurrentCulture = newlanguage;

                            OverrideDateValidation(newlanguage);
                        }
                    );
                }
            );
        }

    }


    function methodDateParse(dateVal, element, param) {

        var date = Globalize.parseDate(dateVal, "dd MMM yyyy");

        var o = $.parseJSON(param);
        var otherValue = null;

        if (typeof o.minDate != "undefined") {
            otherValue = o.minDate;
        }
        else if (typeof o.maxDate != "undefined") {
            otherValue = o.maxDate;
        }
        else if (typeof o.compareName != "undefined") {
            var id = $(element).attr("id");
            var selector = id == null ? "#" + o.compareName : "#" + id.replace(o.propertyName, o.compareName);
            otherValue = $(selector).val();

            if (date != null)
            {
                if (typeof o.compareToOffsetYears == "number" && o.compareToOffsetYears != 0)
                    date.setFullYear(date.getFullYear() + o.compareToOffsetYears);

                if (typeof o.compareToOffsetMonths == "number" && o.compareToOffsetMonths != 0)
                    date.setMonth(date.getMonth() + o.compareToOffsetMonths);

                if (typeof o.compareToOffsetDays == "number" && o.compareToOffsetDays != 0)
                    date.setDate(date.getDate() + o.compareToOffsetDays);
            }
        }

        var otherDate = Globalize.parseDate(otherValue, "dd MMM yyyy");

        if (typeof o.currentYear != "undefined") {
            otherDate = new Date(date);
            otherDate.setFullYear(o.currentYear);
        }

        return { date: date, otherDate: otherDate };
    }

    function yearCheck(value, element, param)
    {
        var d = methodDateParse(value, element, param);

        if (d.date.toString() == d.otherDate.toString()) {
            setTimeout(function () {

                var $e = $(element);

                var msg = $('<span class="val-warning-msg"></span>');
                var text = $e.data('val-yearcheck');

                msg.text(text);

                $('[data-valmsg-for="' + $e.attr('name') + '"]:hidden')
                    .attr('class', 'field-validation-error')
                    .empty()
                    .append(msg);

                if (!$e.data("notifydate") || $e.data("notifydate").toString() != d.date.toString())
                {
                    showMessageBox(text);

                    $e.data("notifydate", d.date);
                }

            }, 100);
        }

        return true;
    }

    $(document).ready(function () {
        CheckCulture("en-US");

        var comparisons = [{ name: "datelessthan", op: "<" }, { name: "dateequalto", op: "==" }, { name: "dategreaterthan", op: ">" },
            { name: "datelessorequal", op: "<=" }, { name: "dategreaterorequal", op:">=" }, { name: "mindate", op:">=" }, { name: "maxdate", op:"<=" }];

        $.each(comparisons, function (i, comparison) {

            $.validator.addMethod(comparison.name, new Function("value, element, param", "var d = methodDateParse(value, element, param); return (d.date == null || d.otherDate == null) || d.date " + comparison.op + " d.otherDate;"));

            $.validator.unobtrusive.adapters.add(comparison.name, ["value"], function (options) {
                options.rules[comparison.name] = options.params.value;
                options.messages[comparison.name] = options.message;
            });            
        });

        $.validator.addMethod("yearcheck", yearCheck);

        $.validator.unobtrusive.adapters.add("yearcheck", ["value"], function (options) {
            options.rules["yearcheck"] = options.params.value;
            options.messages["yearcheck"] = options.message;
        });

        $.validator.addMethod(
            'notequalto',
           function (value, element, params) {

               if (this.optional(element)) {
                   return true;
               }

               var id = $(element).attr("id");
               var selector = id == null ? "#" + params.other : "#" + id.replace(params.property, params.other);
               var otherValue = $(element).closest("[data-address-name]").find(selector).val();

               return (otherValue != value);
           });

        $.validator.unobtrusive.adapters.add(
            'notequalto', ['other', "property"], function (options) {
                var params = {
                    other: options.params.other,
                    property: options.params.property
                };
                options.rules['notequalto'] = params;
                options.messages['notequalto'] = options.message;
            });
    });    





